export type StaticFlowItemGroup = {
  /** A stable key for the repeatable header group. */
  key: string;
  /** Repeat the group header if this group resumes on a later virtual page. */
  repeatHeader?: boolean;
};

export type StaticFlowFragmentContext<TItem = unknown> = {
  flowId: string;
  pageIndex: number;
  pageCount: number;
  itemIndex: number;
  itemKey: React.Key;
  item: TItem;
  groupKey?: string;
  isFirst: boolean;
  isLast: boolean;
  isFirstInFragment: boolean;
  isLastInFragment: boolean;
  isFirstInGroup: boolean;
  isFirstInGroupOnPage: boolean;
  /** This item is on a virtual continuation page of the Flow. */
  isContinuation: boolean;
  /** This group resumes from the preceding virtual page. */
  isGroupContinuation: boolean;
  /**
   * Present on every piece of an item split between the lines of its `Static.FlowText` (0-based
   * `part` of `parts`, the piece's text offsets `[from, to)`); absent for an item rendered whole
   * and in the measurement copy, which renders the whole item.
   */
  split?: { part: number; parts: number; from: number; to: number };
};

export type StaticFlowUnplaceableItem = {
  index: number;
  key: string;
  height: number;
  headerHeight: number;
  requiredHeight: number;
  availableHeight: number;
  /** Present when the item belongs to a FlowColumns track. */
  columnId?: string;
  groupKey?: string;
  reason: 'item-too-tall' | 'item-with-header-too-tall';
};

export type StaticFlowUnplaceableContext = {
  flowId: string;
  pageIndex: number;
  pageCount: number;
};

export type StaticFlowGroupHeaderFragment = {
  groupKey: string;
  itemIndex: number;
  isContinuation: boolean;
};

export type StaticFlowChunk = {
  /** Flattened visual reading order for this page; `layout` preserves parallel track identity. */
  indexes: number[];
  keys: string[];
  /** Track-local source predecessor for the first item in this continuation fragment. */
  previousSourceIndex?: number;
  /** Header insertion points for this exact measured virtual-page fragment. */
  groupHeaders?: StaticFlowGroupHeaderFragment[];
  /** A finite, renderable error page for a row that cannot fit on an empty page. */
  unplaceable?: StaticFlowUnplaceableItem;
  /** Authoritative one-level sequential/parallel fragment plan for FlowColumns. */
  layout?: StaticFlowLayoutFragment[];
  /** The pieces of split items on this page, by item index (`Static.FlowText`). */
  splits?: Record<number, StaticFlowTextSplit>;
};

export type StaticFlowColumn = {
  id: string;
  indexes: number[];
};

export type StaticFlowLayoutNode =
  | { kind: 'item'; index: number }
  | { kind: 'columns'; id: string; columns: StaticFlowColumn[] };

export type StaticFlowColumnFragment = {
  id: string;
  chunk: StaticFlowChunk;
};

export type StaticFlowLayoutFragment =
  | { kind: 'items'; chunk: StaticFlowChunk }
  | { kind: 'columns'; id: string; columns: StaticFlowColumnFragment[] };

type StaticFlowPlanInput = {
  heights?: number[];
  keys?: string[];
  metas?: StaticFlowItemMeta[];
  availableHeight?: number;
  /** The region of every page after the first; defaults to `availableHeight`. */
  continuationHeight?: number;
  headerGroupKeys?: Array<string | undefined>;
  headerGroupHeights?: Record<string, number>;
  headerGroupRepeats?: Record<string, boolean>;
  columnHeaderGroupHeights?: Record<string, Record<string, Record<string, number>>>;
  columnHeaderGroupRepeats?: Record<string, Record<string, Record<string, boolean>>>;
  onUnplaceableItem?: (item: StaticFlowUnplaceableItem) => void;
  /** Line metrics per item (`Static.flowMeasure.readFlowTextLines`); items without are whole. */
  lines?: Array<StaticFlowItemLines | undefined>;
};

const planFlowChunks = distributeFlowItems as (
  input?: StaticFlowPlanInput
) => StaticFlowChunk[];
const planFlowColumnChunks = distributeFlowColumns as (
  input: StaticFlowPlanInput & { nodes: StaticFlowLayoutNode[] }
) => StaticFlowChunk[];

export type StaticFlowMeasurement = {
  flowId: string;
  chunks: StaticFlowChunk[];
  signature: string;
  unplaceableItems?: StaticFlowUnplaceableItem[];
};

export type StaticFlowContextValue = {
  mode: 'measure' | 'visible';
  pageIndex: number;
  measurementVersion?: string;
  pageKey?: string;
  readiness?: ReturnType<typeof paginationReadiness.createScope>;
  chunksByFlowId?: Record<string, StaticFlowChunk[]>;
  registerMeasurement?: (measurement: StaticFlowMeasurement, owner?: string) => void;
  unregisterMeasurement?: (flowId: string, owner: string) => void;
  /**
   * The first measurement copy: asks its host to render the page as a continuation too, for a
   * FlowArea with `measureContinuation`. Returns the release.
   */
  requestContinuation?: () => () => void;
  /**
   * `continuation`: the copy that renders the page as its second sheet. Its FlowAreas only lay
   * out (the first copy's FlowArea reads their height) and its Flows render no items.
   */
  copy?: 'continuation';
};

/** Wraps the continuation measurement copy inside a page's measurement host. */
export const CONTINUATION_COPY_ATTRIBUTE = 'data-uhuu-flow-continuation-copy';

export const StaticFlowContext = React.createContext<StaticFlowContextValue | null>(null);

type FlowAreaProps = {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  /** Receives the same measured plan that drives virtual continuation pages. */
  onFlowMeasurement?: (measurement: StaticFlowMeasurement) => void;
  /**
   * Continuation sheets lay this area out at another height (a title on the first sheet only):
   * PageEditor also measures the page as a continuation and plans later sheets with that height.
   */
  measureContinuation?: boolean;
};

const useIsoLayoutEffect = typeof window === 'undefined' ? React.useEffect : React.useLayoutEffect;

/**
 * An item taller than its region gets a page of its own and renders scaled to fit it, so every
 * document keeps all of its content whatever prints it: nothing is clipped, nothing waits on a
 * renderer to reject the page. Its group header stays full size; the item keeps its own layout.
 */
function unplaceableFitStyle(unplaceable: StaticFlowUnplaceableItem): React.CSSProperties | undefined {
  const room = unplaceable.availableHeight - unplaceable.headerHeight;
  if (!(unplaceable.height > 0) || !Number.isFinite(room)) return undefined;
  const scale = Math.min(1, Math.max(room, 1) / unplaceable.height);
  return scale < 1 ? { transform: `scale(${scale})`, transformOrigin: 'top left' } : undefined;
}
const warnedMetaDefaultsWithoutType = new Set<string>();

type FlowItemType<TItem> = TItem extends { type?: infer TType }
  ? Extract<TType, string>
  : string;

type DefaultFlowItemType<TItem> = [FlowItemType<TItem>] extends [never]
  ? string
  : FlowItemType<TItem>;

function getItemType(item: unknown): string | undefined {
  if (!item || typeof item !== 'object' || !('type' in item)) return undefined;
  const type = (item as { type?: unknown }).type;
  return typeof type === 'string' || typeof type === 'number' ? String(type) : undefined;
}

function mergeItemMeta(
  base: StaticFlowItemMeta | undefined,
  override: StaticFlowItemMeta | undefined
): StaticFlowItemMeta {
  const merged: StaticFlowItemMeta = { ...(base ?? {}) };

  for (const [key, value] of Object.entries(override ?? {})) {
    if (value !== undefined) {
      (merged as Record<string, unknown>)[key] = value;
    }
  }

  return merged;
}

function numericStyle(value: string) {
  return Number.parseFloat(value || '0') || 0;
}

function assertSupportedFlowColumnGeometry(flow: HTMLElement, scale: number) {
  const verticalBox = (element: HTMLElement) => {
    const style = window.getComputedStyle(element);
    return numericStyle(style.paddingTop) +
      numericStyle(style.paddingBottom) +
      numericStyle(style.borderTopWidth) +
      numericStyle(style.borderBottomWidth);
  };
  for (const group of Array.from(
    flow.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-layout-node="columns"]')
  )) {
    const groupStyle = window.getComputedStyle(group);
    const groupVerticalMargins =
      numericStyle(groupStyle.marginTop) + numericStyle(groupStyle.marginBottom);
    if (verticalBox(group) > 0.01 || groupVerticalMargins > 0.01) {
      throw new TypeError(
        '[uhuu-components] Static.FlowColumns group vertical margin, padding, and borders are unsupported; ' +
        'put measured vertical spacing on items with getColumnItemProps.'
      );
    }
    const naturalColumnHeights: number[] = [];
    for (const column of Array.from(
      group.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-column]')
    )) {
      const style = window.getComputedStyle(column);
      const verticalMargins = numericStyle(style.marginTop) + numericStyle(style.marginBottom);
      if (
        verticalBox(column) > 0.01 ||
        verticalMargins > 0.01 ||
        numericStyle(style.rowGap) > 0.01 ||
        numericStyle(style.minHeight) > 0.01 ||
        style.maxHeight !== 'none'
      ) {
        throw new TypeError(
          '[uhuu-components] Static.FlowColumns column vertical margin, padding, borders, min/max height, and row-gap are unsupported; ' +
          'put measured vertical spacing on items with getColumnItemProps.'
        );
      }
      const naturalHeight = Array.from(
        column.querySelectorAll<HTMLElement>(
          '[data-uhuu-flow-item="true"], [data-uhuu-flow-group-header="true"]'
        )
      ).reduce((sum, child) => sum + getOuterHeight(child, scale), 0);
      naturalColumnHeights.push(naturalHeight);
    }
    const naturalGroupHeight = Math.max(0, ...naturalColumnHeights);
    if (getOuterHeight(group, scale) > naturalGroupHeight + 1) {
      throw new TypeError(
        '[uhuu-components] Static.FlowColumns group/column fixed height or wrapping adds unmeasured vertical extent.'
      );
    }
  }
}

type BuildChunksOptions = {
  onZeroHeight?: () => void;
  onUnplaceableItem?: (item: StaticFlowUnplaceableItem) => void;
  /** An `asChild` Flow rendered items whose element does not carry the flow's attributes. */
  onUnmarkedItems?: (marked: number, rendered: number) => void;
  /** The continuation copy's region height (`measureContinuation`). */
  continuationHeight?: number;
  /** An item's `Static.FlowText` cannot split, or may not match its plan (development warnings). */
  onFlowTextIssue?: (issue: StaticFlowTextIssue | 'flow-text-in-columns') => void;
};

/**
 * An `asChild` Flow says how many items it rendered: a component that does not pass its props on
 * to a DOM element drops the flow's attributes, and the plan would index the wrong items.
 */
function checkMarkedItems(flow: HTMLElement, itemElements: HTMLElement[], options: BuildChunksOptions) {
  const rendered = flow.dataset.uhuuFlowItemCount;
  if (rendered === undefined) return;
  const count = Number.parseInt(rendered, 10);
  if (Number.isInteger(count) && count !== itemElements.length) {
    options.onUnmarkedItems?.(itemElements.length, count);
  }
}

const roundHeight = (height: number | undefined) => (
  height === undefined ? undefined : Math.round(height * 100) / 100
);

const FLOW_TEXT_SELECTOR = '[data-uhuu-flow-text]';

/** Line metrics in a signature: rounded as heights are, so a re-wrap re-plans and noise does not. */
const roundLines = (entry: StaticFlowItemLines | undefined) => (
  entry
    ? {
      lines: entry.lines.map(({ top, bottom, start, hyphen }) => (
        hyphen ? [roundHeight(top), roundHeight(bottom), start, 1] : [roundHeight(top), roundHeight(bottom), start]
      )),
      end: entry.end,
      justify: entry.justify,
    }
    : null
);

function buildChunks(
  area: HTMLElement,
  flow: HTMLElement,
  options: BuildChunksOptions = {}
): StaticFlowMeasurement | null {
  const flowId = flow.dataset.uhuuFlowId;
  if (!flowId) return null;

  if (flow.dataset.uhuuFlowLayout === 'columns') {
    return buildFlowColumnChunks(area, flow, options);
  }

  const itemElements = readFlowItemElements(flow);
  checkMarkedItems(flow, itemElements, options);
  if (!itemElements.length) {
    return {
      flowId,
      chunks: [{ indexes: [], keys: [] }],
      signature: `${flowId}:empty`,
      unplaceableItems: [],
    };
  }

  const areaRect = area.getBoundingClientRect();
  // Normalize every rect read back to layout space so a scaled preview (fit-to-pane, host zoom)
  // measures the exact same chunk plan as the unscaled published document.
  const scale = getEffectiveScale(area);
  const measuredAvailableHeight = areaRect.height ? areaRect.height / scale : area.clientHeight;
  const hasAvailableHeight = Number.isFinite(measuredAvailableHeight) && measuredAvailableHeight > 0;
  const unwrapped = flow.dataset.uhuuFlowAsChild === 'true' ? readUnwrappedHeights(area, flow, scale) : undefined;
  const heights = itemElements.map((item) => unwrapped?.get(item) ?? getOuterHeight(item, scale));
  const metas = itemElements.map(readItemMeta);
  const keys = itemElements.map((item, index) => item.dataset.uhuuFlowKey || String(index));
  const headerGroupKeys = itemElements.map(readHeaderGroupKey);
  const headerGroupRepeats = readHeaderGroupRepeats(itemElements);
  const headerGroupHeights = readHeaderGroupHeights(flow, scale, unwrapped);
  const continuationHeight = hasAvailableHeight ? options.continuationHeight : undefined;
  const unplaceableItems: StaticFlowUnplaceableItem[] = [];
  const fallbackHeight = hasAvailableHeight
    ? measuredAvailableHeight
    : heights.reduce((sum, height) => sum + height, 0) +
      Object.values(headerGroupHeights).reduce((sum, height) => sum + height, 0);
  // Items that may split between lines. A flow without Static.FlowText reads nothing more, and its
  // plan and signature are exactly those of an item-level flow. With one, an item's lines are read
  // when the planner asks for them, which it does only for an item that does not fit whole: a pass
  // costs what the pages' splits cost, not what every text in the flow holds.
  const hasLines = Boolean(flow.querySelector(FLOW_TEXT_SELECTOR));
  const readLines = new Map<number, StaticFlowItemLines | undefined>();
  const lines = hasLines ? new Array<StaticFlowItemLines | undefined>(itemElements.length) : undefined;
  if (lines) {
    itemElements.forEach((item, index) => {
      if (!item.querySelector(FLOW_TEXT_SELECTOR)) return;
      Object.defineProperty(lines, index, {
        enumerable: true,
        get: () => {
          if (!readLines.has(index)) {
            readLines.set(index, readFlowTextLines(item, heights[index], scale, options.onFlowTextIssue));
          }
          return readLines.get(index);
        },
      });
    });
  }

  if (!hasAvailableHeight) {
    options.onZeroHeight?.();
  }

  const finalChunks = planFlowChunks({
    heights,
    keys,
    metas,
    availableHeight: fallbackHeight,
    continuationHeight,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    onUnplaceableItem: (item: StaticFlowUnplaceableItem) => {
      unplaceableItems.push(item);
      options.onUnplaceableItem?.(item);
    },
    ...(hasLines ? { lines } : {}),
  });
  const signature = hashString(JSON.stringify({
    version: hasLines ? 4 : 2,
    flowId,
    availableHeight: Math.round(fallbackHeight * 100) / 100,
    continuationHeight: roundHeight(continuationHeight),
    heights: heights.map((height) => Math.round(height * 100) / 100),
    keys,
    metas,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    unplaceableItems,
    // The lines the plan read: those of the other items cannot change it (they are placed whole).
    ...(hasLines
      ? { lines: [...readLines].sort(([a], [b]) => a - b).map(([index, entry]) => [index, roundLines(entry)]) }
      : {}),
  }));

  return { flowId, chunks: finalChunks, signature, unplaceableItems };
}

function buildFlowColumnChunks(
  area: HTMLElement,
  flow: HTMLElement,
  options: BuildChunksOptions = {}
): StaticFlowMeasurement | null {
  const flowId = flow.dataset.uhuuFlowId;
  if (!flowId) return null;
  const itemElements = readFlowItemElements(flow);
  checkMarkedItems(flow, itemElements, options);
  if (!itemElements.length) {
    return {
      flowId,
      chunks: [{ indexes: [], keys: [], layout: [] }],
      signature: `${flowId}:columns:empty`,
      unplaceableItems: [],
    };
  }

  const areaRect = area.getBoundingClientRect();
  const scale = getEffectiveScale(area);
  assertSupportedFlowColumnGeometry(flow, scale);
  // Line splitting is not planned across columns: such items render whole.
  if (flow.querySelector(FLOW_TEXT_SELECTOR)) options.onFlowTextIssue?.('flow-text-in-columns');
  const measuredAvailableHeight = areaRect.height ? areaRect.height / scale : area.clientHeight;
  const hasAvailableHeight = Number.isFinite(measuredAvailableHeight) && measuredAvailableHeight > 0;
  const highestIndex = Math.max(
    -1,
    ...itemElements.map((item) => Number.parseInt(item.dataset.uhuuFlowIndex ?? '-1', 10))
  );
  const heights = Array.from({ length: highestIndex + 1 }, () => 0);
  const keys = Array.from({ length: highestIndex + 1 }, (_, index) => String(index));
  const metas = Array.from({ length: highestIndex + 1 }, () => ({} as StaticFlowItemMeta));
  const headerGroupKeys = Array.from(
    { length: highestIndex + 1 },
    () => undefined as string | undefined
  );
  const unwrapped = flow.dataset.uhuuFlowAsChild === 'true' ? readUnwrappedHeights(area, flow, scale) : undefined;
  for (const item of itemElements) {
    const index = Number.parseInt(item.dataset.uhuuFlowIndex ?? '-1', 10);
    if (!Number.isInteger(index) || index < 0) continue;
    heights[index] = unwrapped?.get(item) ?? getOuterHeight(item, scale);
    keys[index] = item.dataset.uhuuFlowKey || String(index);
    metas[index] = readItemMeta(item);
    headerGroupKeys[index] = readHeaderGroupKey(item);
  }
  const nodes = Array.from(flow.children).flatMap((node): StaticFlowLayoutNode[] => {
    if (!(node instanceof HTMLElement)) return [];
    if (node.dataset.uhuuFlowLayoutNode === 'item') {
      const item = node.matches('[data-uhuu-flow-item="true"]')
        ? node
        : node.querySelector<HTMLElement>('[data-uhuu-flow-item="true"]');
      const index = Number.parseInt(item?.dataset.uhuuFlowIndex ?? '-1', 10);
      return Number.isInteger(index) && index >= 0 ? [{ kind: 'item', index }] : [];
    }
    if (node.dataset.uhuuFlowLayoutNode !== 'columns') return [];
    const columns = Array.from(
      node.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-column]')
    ).flatMap((column): StaticFlowColumn[] => {
      const id = column.dataset.uhuuFlowColumn;
      if (!id) return [];
      const indexes = Array.from(
        column.querySelectorAll<HTMLElement>('[data-uhuu-flow-item="true"]')
      ).map((item) => Number.parseInt(item.dataset.uhuuFlowIndex ?? '-1', 10))
        .filter((index) => Number.isInteger(index) && index >= 0);
      return [{ id, indexes }];
    });
    return columns.length
      ? [{ kind: 'columns', id: node.dataset.uhuuFlowLayoutId || 'columns', columns }]
      : [];
  });
  const headerGroupRepeats = readHeaderGroupRepeats(itemElements);
  const headerGroupHeights = readHeaderGroupHeights(flow, scale, unwrapped);
  const continuationHeight = hasAvailableHeight ? options.continuationHeight : undefined;
  const columnHeaderGroupHeights: Record<string, Record<string, Record<string, number>>> = {};
  const columnHeaderGroupRepeats: Record<string, Record<string, Record<string, boolean>>> = {};
  for (const group of Array.from(
    flow.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-layout-node="columns"]')
  )) {
    const groupId = group.dataset.uhuuFlowLayoutId;
    if (!groupId) continue;
    columnHeaderGroupHeights[groupId] = {};
    columnHeaderGroupRepeats[groupId] = {};
    for (const column of Array.from(
      group.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-column]')
    )) {
      const columnId = column.dataset.uhuuFlowColumn;
      if (!columnId) continue;
      const columnItems = Array.from(
        column.querySelectorAll<HTMLElement>('[data-uhuu-flow-item="true"]')
      );
      columnHeaderGroupHeights[groupId][columnId] = readHeaderGroupHeights(column, scale);
      columnHeaderGroupRepeats[groupId][columnId] = readHeaderGroupRepeats(columnItems);
    }
  }
  const unplaceableItems: StaticFlowUnplaceableItem[] = [];
  const fallbackHeight = hasAvailableHeight
    ? measuredAvailableHeight
    : heights.reduce((sum, height) => sum + height, 0) +
      Object.values(headerGroupHeights).reduce((sum, height) => sum + height, 0);
  if (!hasAvailableHeight) options.onZeroHeight?.();

  const chunks = planFlowColumnChunks({
    nodes,
    heights,
    keys,
    metas,
    availableHeight: fallbackHeight,
    continuationHeight,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    columnHeaderGroupHeights,
    columnHeaderGroupRepeats,
    onUnplaceableItem: (item: StaticFlowUnplaceableItem) => {
      unplaceableItems.push(item);
      options.onUnplaceableItem?.(item);
    },
  });
  const signature = hashString(JSON.stringify({
    version: 3,
    flowId,
    availableHeight: Math.round(fallbackHeight * 100) / 100,
    continuationHeight: roundHeight(continuationHeight),
    nodes,
    heights: heights.map((height) => Math.round(height * 100) / 100),
    keys,
    metas,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    columnHeaderGroupHeights,
    columnHeaderGroupRepeats,
    unplaceableItems,
  }));
  return { flowId, chunks, signature, unplaceableItems };
}

const FLOW_TEXT_ISSUES: Record<Exclude<StaticFlowTextIssue, 'unsupported-content'> | 'flow-text-in-columns', string> = {
  'multiple-flow-text': 'an item holds more than one Static.FlowText, so it is not split. Give each item one FlowText.',
  'inline-flow-text': 'a Static.FlowText is not a block element (as="span"?), so its lines are not its own and its ' +
    'item is not split. Keep the default `as="div"` or another block element.',
  'rewrapping-text-wrap': 'a Static.FlowText has text-wrap: balance or pretty, which re-flows each piece of a split ' +
    'item, so a piece may not match its planned lines. Use text-wrap: wrap on split text.',
  'flow-text-in-columns': 'Static.FlowColumns does not split Static.FlowText items; they render whole.',
};

/**
 * The FlowArea of `flowId` in the page's continuation measurement copy, if the host renders one.
 */
function findContinuationArea(root: HTMLElement, flowId: string): HTMLElement | null {
  for (const flow of Array.from(
    root.querySelectorAll<HTMLElement>(`[${CONTINUATION_COPY_ATTRIBUTE}] [data-uhuu-flow="true"]`)
  )) {
    if (flow.dataset.uhuuFlowId === flowId) return flow.closest<HTMLElement>('[data-uhuu-flow-area]');
  }
  return null;
}

export function FlowArea({
  children,
  className = '',
  style,
  onFlowMeasurement,
  measureContinuation = false,
}: FlowAreaProps) {
  const context = React.useContext(StaticFlowContext);
  const areaRef = React.useRef<HTMLDivElement>(null);
  const owner = React.useId();
  const registeredFlowId = React.useRef<string | null>(null);
  const latestContext = React.useRef(context);
  const lastSignatureRef = React.useRef<string>('');
  const warnedMultipleFlowsRef = React.useRef(false);
  const warnedZeroHeightRef = React.useRef(false);
  const warnedUnplaceableItemsRef = React.useRef(new Set<string>());
  const warnedIdFailureRef = React.useRef('');
  const warnedContinuationRef = React.useRef('');
  const warnedUnmarkedRef = React.useRef('');
  const warnedFlowTextRef = React.useRef(new Set<string>());

  // A FlowArea removed from its page lets the measurement host drop plans for flows it no longer
  // renders (also one never measured). When the whole hidden copy goes, the plans stay for the next host.
  React.useEffect(() => () => {
    latestContext.current?.unregisterMeasurement?.(registeredFlowId.current ?? '', owner);
  }, [owner]);

  // The first measurement copy asks its host for a continuation copy while this area needs one.
  useIsoLayoutEffect(() => {
    if (!measureContinuation) return undefined;
    return context?.requestContinuation?.();
  }, [context, measureContinuation]);

  useIsoLayoutEffect(() => {
    latestContext.current = context;
    if (context?.mode !== 'measure' || !context.registerMeasurement || !areaRef.current) {
      return;
    }

    const area = areaRef.current;
    // The page's whole hidden copy: header and footer images change the area's height too. With
    // `measureContinuation` it holds the continuation copy as well, whose assets size that region.
    const root = area.closest<HTMLElement>('[data-uhuu-flow-measurement]') ?? area;
    // Only the first copy measures: a continuation copy's areas lay out for it to read.
    const continuation = measureContinuation && Boolean(context.requestContinuation);
    let cancelScheduledMeasure: (() => void) | null = null;
    let finishScheduledMeasure: (() => void) | undefined;
    let resizeObserver: ResizeObserver | null = null;
    let observedContinuationArea: HTMLElement | null = null;
    lastSignatureRef.current = '';

    // `hold`: keep pagination `measuring` until this measurement runs. Changes in the area, its size
    // and asset loads hold; a change elsewhere in the page (a header that updates every second)
    // only remeasures, and pagination reacts only if the plan changes, so it can still settle.
    const scheduleMeasure = (hold = true) => {
      // Coalesce all observer notifications arriving in one frame. Unlike
      // cancelling and re-queuing, this cannot postpone a remeasure forever
      // while an editable surface is continuously mutating. The frame falls
      // back to a timeout: a hidden document runs no animation frames.
      if (hold && !finishScheduledMeasure) finishScheduledMeasure = readiness?.begin();
      if (cancelScheduledMeasure !== null) return;
      cancelScheduledMeasure = scheduleFlowFrame(() => {
        cancelScheduledMeasure = null;
        try {
          measure();
        } catch (error) {
          lastSignatureRef.current = '';
          readiness?.fail(error);
          area.setAttribute('data-uhuu-flow-error', String(error));
          console.error('[uhuu-components] Flow measurement failed:', error);
        } finally {
          finishScheduledMeasure?.();
          finishScheduledMeasure = undefined;
        }
      });
    };
    const readiness = context.readiness?.registerArea(context.pageKey ?? '', { remeasure: () => scheduleMeasure() });

    const observedMeasurementElements = new Set<HTMLElement>();
    const observeMeasurementElements = () => {
      if (!resizeObserver) return;

      for (const element of Array.from(observedMeasurementElements)) {
        if (!area.contains(element)) {
          resizeObserver.unobserve(element);
          observedMeasurementElements.delete(element);
        }
      }

      area
        .querySelectorAll<HTMLElement>(
          '[data-uhuu-flow-item="true"], [data-uhuu-flow-group-header="true"]'
        )
        .forEach((element) => {
          if (observedMeasurementElements.has(element)) return;
          observedMeasurementElements.add(element);
          resizeObserver?.observe(element);
        });
    };

    const report = (failure: string | null) => {
      if (failure) area.setAttribute('data-uhuu-flow-error', failure);
      else area.removeAttribute('data-uhuu-flow-error');
    };

    // The continuation copy's region for this flow: its height, or why it has none.
    const readContinuation = (flowId: string): { height?: number; failure?: string } => {
      const continuationArea = findContinuationArea(root, flowId);
      if (continuationArea !== observedContinuationArea) {
        if (observedContinuationArea) resizeObserver?.unobserve(observedContinuationArea);
        if (continuationArea) resizeObserver?.observe(continuationArea);
        observedContinuationArea = continuationArea;
      }
      if (!continuationArea) return { failure: 'missing-continuation-flow' };
      const rect = continuationArea.getBoundingClientRect();
      const height = rect.height
        ? rect.height / getEffectiveScale(continuationArea)
        : continuationArea.clientHeight;
      return Number.isFinite(height) && height > 0 ? { height } : { failure: 'unmeasurable-flow-area' };
    };

    function measure() {
      observeMeasurementElements();

      const flows = area.querySelectorAll<HTMLElement>('[data-uhuu-flow="true"]');
      if (flows.length > 1 && !warnedMultipleFlowsRef.current && isDev()) {
        warnedMultipleFlowsRef.current = true;
        console.warn(
          '[uhuu-components] Static.FlowArea supports one Static.Flow child. ' +
          'Additional Static.Flow elements in the same area are ignored. Use one FlowArea per flow region.'
        );
      }

      const flow = flows[0];
      const flowId = flow?.dataset.uhuuFlowId;
      if (registeredFlowId.current && registeredFlowId.current !== flowId) {
        context?.unregisterMeasurement?.(registeredFlowId.current, owner);
        registeredFlowId.current = null;
        lastSignatureRef.current = '';
      }
      if (!flow) {
        // Pending, not failed: the flow may still render (data loading). Say why it waits.
        report('missing-flow');
        readiness?.clear();
        return;
      }
      // Plans are keyed by flow id per page: a flow without one cannot be paginated, and two flows
      // sharing one overwrite each other's plan. Report both instead of waiting for a plan that
      // never matches; a shared id still paginates as it always did, so the output is unchanged.
      const sameId = flowId
        ? Array.from(root.querySelectorAll<HTMLElement>('[data-uhuu-flow="true"]'))
          .filter((candidate) => (
            candidate.dataset.uhuuFlowId === flowId &&
            !candidate.closest(`[${CONTINUATION_COPY_ATTRIBUTE}]`)
          )).length
        : 0;
      const idFailure = !flowId ? 'missing-flow-id' : sameId > 1 ? 'duplicate-flow-id' : null;
      if (idFailure && isDev() && warnedIdFailureRef.current !== `${idFailure}:${flowId}`) {
        warnedIdFailureRef.current = `${idFailure}:${flowId}`;
        console.warn(
          `[uhuu-components] Static.Flow ${flowId ? `id "${flowId}" is used by more than one Flow` : 'has no id'} ` +
          `on page "${context?.pageKey ?? ''}". Give each Flow on a page a stable, unique id.`
        );
      }
      if (!flowId) {
        lastSignatureRef.current = '';
        report('missing-flow-id');
        readiness?.fail('missing-flow-id');
        return;
      }

      let failure: string | null = idFailure ?? (flows.length > 1 ? 'multiple-flows-in-area' : null);
      const continuationRead = continuation ? readContinuation(flowId) : undefined;
      const measurement = buildChunks(area, flow, {
        continuationHeight: continuationRead?.height,
        onUnmarkedItems: (marked, rendered) => {
          failure ??= 'unmarked-flow-item';
          if (!isDev() || warnedUnmarkedRef.current === flowId) return;
          warnedUnmarkedRef.current = flowId;
          console.warn(
            `[uhuu-components] Static.Flow "${flowId}" asChild: ${rendered - marked} of ${rendered} items carry no ` +
            'flow attributes, so the flow cannot be paginated. renderItem must return a DOM element, or a ' +
            'component that passes the props it receives on to its root DOM element.'
          );
        },
        onZeroHeight: () => {
          // A region with no layout box (`display: none` on it or an ancestor) never prints, so it
          // is not an export error. Its flow is the test: a `display: contents` area has no box of
          // its own while its items lay out, and that is an unmeasurable area.
          if (!flow.getClientRects().length) return;
          failure = 'unmeasurable-flow-area';
          if (warnedZeroHeightRef.current || !isDev()) return;
          warnedZeroHeightRef.current = true;
          console.warn(
            '[uhuu-components] Static.FlowArea has flow items but no measurable height. ' +
            'Give the area an explicit height or use a constrained flex layout such as flex-1 min-h-0.'
          );
        },
        onFlowTextIssue: (issue) => {
          // FlowText names its unsupported content itself.
          if (issue === 'unsupported-content' || !isDev()) return;
          const warning = `${flowId}:${issue}`;
          if (warnedFlowTextRef.current.has(warning)) return;
          warnedFlowTextRef.current.add(warning);
          console.warn(`[uhuu-components] Static.Flow "${flowId}": ${FLOW_TEXT_ISSUES[issue]}`);
        },
        onUnplaceableItem: (item) => {
          if (warnedUnplaceableItemsRef.current.has(item.key)) return;
          warnedUnplaceableItemsRef.current.add(item.key);
          console.warn(
            `[uhuu-components] Static.Flow item "${item.key}" cannot fit in its FlowArea ` +
            `(${Math.round(item.requiredHeight)}px required > ${Math.round(item.availableHeight)}px available). ` +
            'It prints on a page of its own, scaled to fit. Put its long text in a Static.FlowText, split the item, ' +
            'or reduce its height.'
          );
        },
      });
      if (!measurement) return;
      // A continuation region only matters once the flow needs continuation sheets.
      const continuationFailure = measurement.chunks.length > 1 ? continuationRead?.failure : undefined;
      if (continuationFailure && isDev() && warnedContinuationRef.current !== `${continuationFailure}:${flowId}`) {
        warnedContinuationRef.current = `${continuationFailure}:${flowId}`;
        console.warn(
          `[uhuu-components] Static.FlowArea measureContinuation: page "${context?.pageKey ?? ''}" ` +
          (continuationFailure === 'missing-continuation-flow'
            ? `renders no Static.Flow "${flowId}" on a continuation sheet, so its continuation pages would lose ` +
              'its items. Render the FlowArea and its Flow on every sheet.'
            : `lays the FlowArea of "${flowId}" out at zero height on a continuation sheet. Give it a ` +
              'measurable height there too.')
        );
      }
      if (continuationFailure === 'missing-continuation-flow') {
        // Pending, not failed, like a missing flow: the continuation copy may still be loading.
        // The plan it would replace stays; pagination waits and says why.
        report(continuationFailure);
        readiness?.clear();
        return;
      }
      failure ??= continuationFailure ?? null;
      readiness?.measured(measurement, failure);
      report(failure);
      if (measurement.signature === lastSignatureRef.current) return;

      // The plan first: a template's observer must not be able to keep it from being registered.
      context?.registerMeasurement?.(measurement, owner);
      lastSignatureRef.current = measurement.signature;
      registeredFlowId.current = measurement.flowId;
      try {
        onFlowMeasurement?.(measurement);
      } catch (error) {
        console.error('[uhuu-components] FlowArea onFlowMeasurement threw:', error);
      }
    }

    const assets = observeFlowAssets(root, {
      begin: () => readiness?.begin() ?? (() => {}),
      onReady: () => scheduleMeasure(),
    });
    if (typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(() => scheduleMeasure());
      resizeObserver.observe(area);
    }
    observeMeasurementElements();
    scheduleMeasure();

    // The whole hidden copy, not only the area: a header or footer that changes changes the
    // area's height, and a background document may never deliver the ResizeObserver callback.
    const mutationObserver = new MutationObserver((records) => {
      assets.sync();
      // Reconcile new/removed measured elements in the scheduled pass rather
      // than scanning the complete flow both here and again in `measure`.
      scheduleMeasure(records.some((record) => area.contains(record.target)));
    });
    mutationObserver.observe(root, {
      attributes: true,
      attributeFilter: [
        'class',
        'style',
        'src',
        'srcset',
        'sizes',
        'data-uhuu-flow',
        'data-uhuu-flow-id',
        'data-uhuu-flow-item',
        'data-uhuu-flow-key',
        'data-uhuu-flow-break-before',
        'data-uhuu-flow-break-after',
        'data-uhuu-flow-keep-with-next',
        'data-uhuu-flow-avoid-break-inside',
        'data-uhuu-flow-group-key',
        'data-uhuu-flow-header-group-key',
        'data-uhuu-flow-header-repeat',
        'data-uhuu-flow-group-header',
        'data-uhuu-flow-orphans',
        'data-uhuu-flow-widows',
        'data-uhuu-flow-text',
        'data-uhuu-flow-text-unsplittable',
      ],
      characterData: true,
      childList: true,
      subtree: true,
    });

    return () => {
      if (cancelScheduledMeasure !== null) {
        cancelScheduledMeasure();
        cancelScheduledMeasure = null;
        finishScheduledMeasure?.();
      }
      resizeObserver?.disconnect();
      mutationObserver.disconnect();
      assets.disconnect();
      readiness?.dispose();
    };
  }, [context, onFlowMeasurement, owner, measureContinuation]);

  return (
    <div ref={areaRef} className={className} style={style} data-uhuu-flow-area="true">
      {children}
    </div>
  );
}

type FlowPageProps = {
  children: React.ReactNode;
  header?: React.ReactNode;
  footer?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  flowAreaClassName?: string;
  flowAreaStyle?: React.CSSProperties;
  onFlowMeasurement?: (measurement: StaticFlowMeasurement) => void;
  /** See `FlowArea`: continuation sheets lay the area out at another height. */
  measureContinuation?: boolean;
};

export function FlowPage({
  children,
  header,
  footer,
  className = '',
  style,
  flowAreaClassName = '',
  flowAreaStyle,
  onFlowMeasurement,
  measureContinuation,
}: FlowPageProps) {
  return (
    <div
      className={`uhuu-flow-page ${className}`}
      style={style}
      data-uhuu-flow-page="true"
    >
      {header}
      <FlowArea
        className={`uhuu-flow-page-area ${flowAreaClassName}`}
        style={flowAreaStyle}
        onFlowMeasurement={onFlowMeasurement}
        measureContinuation={measureContinuation}
      >
        {children}
      </FlowArea>
      {footer}
    </div>
  );
}

function normalizeItemGroup(
  value: StaticFlowItemGroup | string | null | undefined
): StaticFlowItemGroup | undefined {
  if (typeof value === 'string') {
    return value ? { key: value, repeatHeader: true } : undefined;
  }

  if (!value?.key) return undefined;
  return {
    key: value.key,
    repeatHeader: value.repeatHeader !== false,
  };
}

/**
 * `getFlowFragmentState` resolves the fragment position with `indexOf`. The
 * renderer already walks every visible index, so prepare the same first-match
 * lookup once instead. Keeping the first position deliberately preserves the
 * core helper's behavior for a stale chunk that happens to contain an index
 * more than once.
 */
function getFirstFragmentPositions(fragmentIndexes: readonly number[]): Map<number, number> {
  const positions = new Map<number, number>();
  fragmentIndexes.forEach((itemIndex, position) => {
    if (!positions.has(itemIndex)) positions.set(itemIndex, position);
  });
  return positions;
}

/**
 * A planned header list is authoritative when it exists, including an empty
 * list. Index it once so a page with many groups does not scan it per item.
 */
function getPlannedGroupHeadersByItemIndex(
  groupHeaders: StaticFlowGroupHeaderFragment[] | undefined
): Map<number, Set<string>> | undefined {
  if (!groupHeaders) return undefined;

  const headersByItemIndex = new Map<number, Set<string>>();
  for (const header of groupHeaders) {
    let groupKeys = headersByItemIndex.get(header.itemIndex);
    if (!groupKeys) {
      groupKeys = new Set<string>();
      headersByItemIndex.set(header.itemIndex, groupKeys);
    }
    groupKeys.add(header.groupKey);
  }
  return headersByItemIndex;
}

type FlowElementProps = {
  className?: string;
  [attribute: `data-${string}`]: string | number | undefined;
};

const warnedAsChild = new Set<string>();

function describeNode(node: React.ReactNode): string {
  if (node === null || node === undefined || typeof node === 'boolean') return 'nothing';
  if (Array.isArray(node)) return 'several nodes';
  if (React.isValidElement(node)) return 'a fragment';
  return 'text';
}

/**
 * `asChild`: the flow's attributes and class names go on the element the template returned (a
 * `<tr>`, an `<li>`), Radix Slot style, so nothing stands between the template's container and its
 * items. Classes are joined; the template's style sits over `baseStyle` (getColumnItemProps) and
 * under `forcedStyle` (an oversized item's fit). The element keeps its own ref and key, and gets no
 * `display: flow-root`. Anything but one element cannot carry the attributes: the caller renders
 * its wrapper instead, and development builds say so once per flow and callback.
 */
function cloneAsChild(
  content: React.ReactNode,
  props: FlowElementProps,
  options: {
    flowId: string;
    source: string;
    baseStyle?: React.CSSProperties;
    forcedStyle?: React.CSSProperties;
  }
): React.ReactElement | null {
  if (React.isValidElement(content) && content.type !== React.Fragment) {
    const own = content.props as { className?: unknown; style?: React.CSSProperties };
    const className = [props.className, typeof own.className === 'string' ? own.className : undefined]
      .filter(Boolean)
      .join(' ') || undefined;
    const style = options.baseStyle || own.style || options.forcedStyle
      ? { ...options.baseStyle, ...own.style, ...options.forcedStyle }
      : undefined;
    return React.cloneElement(content as React.ReactElement<Record<string, unknown>>, {
      ...props,
      className,
      style,
    });
  }
  const warning = `${options.flowId}:${options.source}`;
  if (isDev() && !warnedAsChild.has(warning)) {
    warnedAsChild.add(warning);
    console.warn(
      `[uhuu-components] Static.Flow "${options.flowId}" asChild: ${options.source} returned ` +
      `${describeNode(content)}. asChild needs exactly one element to carry the flow's attributes, ` +
      'so it renders in a wrapper <div> instead.'
    );
  }
  return null;
}

/** `data-uhuu-flow-split` on a piece of a split item. */
function splitPosition(split: StaticFlowTextSplit): 'first' | 'middle' | 'last' {
  if (split.part === 0) return 'first';
  return split.part === split.parts - 1 ? 'last' : 'middle';
}

/**
 * What renderItem's fragment says about a piece: which one it is. A continuation piece resumes its
 * group on the page it opens.
 */
function splitFragment(split: StaticFlowTextSplit, core: { isFirstInGroupOnPage: boolean }) {
  return {
    split: { part: split.part, parts: split.parts, from: split.from, to: split.to },
    ...(split.part > 0 && core.isFirstInGroupOnPage ? { isGroupContinuation: true } : {}),
  };
}

/** Content inside a piece of an outer Flow's item that is not that piece (a nested Flow's items). */
function shadowSplit(node: React.ReactNode) {
  return node === null || node === undefined || node === false
    ? node
    : <FlowTextSplitContext.Provider value={null}>{node}</FlowTextSplitContext.Provider>;
}

type FlowProps<TItem, TType extends string = DefaultFlowItemType<TItem>> = {
  id: string;
  items: TItem[];
  getKey: (item: TItem, index: number) => React.Key;
  /** The third argument describes this item's visible virtual-page fragment. */
  renderItem: (
    item: TItem,
    index: number,
    fragment: StaticFlowFragmentContext<TItem>
  ) => React.ReactNode;
  getItemMeta?: (item: TItem, index: number) => StaticFlowItemMeta | undefined;
  metaDefaults?: Partial<Record<TType, StaticFlowItemMeta>>;
  getItemType?: (item: TItem, index: number) => TType | undefined;
  /** Opt into a separately measured, repeatable group header. */
  getItemGroup?: (
    item: TItem,
    index: number
  ) => StaticFlowItemGroup | string | null | undefined;
  renderGroupHeader?: (
    group: StaticFlowItemGroup,
    fragment: StaticFlowFragmentContext<TItem>
  ) => React.ReactNode;
  className?: string;
  itemClassName?: string | ((item: TItem, index: number) => string | undefined);
  groupHeaderClassName?: string | ((
    group: StaticFlowItemGroup,
    fragment: StaticFlowFragmentContext<TItem>
  ) => string | undefined);
  renderUnplaceableItem?: (
    item: StaticFlowUnplaceableItem,
    context: StaticFlowUnplaceableContext
  ) => React.ReactNode;
  /**
   * Render each item as the element `renderItem` returns, carrying the flow's attributes, instead
   * of inside a wrapper `<div>` (also group headers and a custom unplaceable fallback). For rows of
   * a table or items of a list, with `as`.
   */
  asChild?: boolean;
  /** The Flow's root element. Default `div`; `tbody`, `ul` or `ol` with `asChild`. */
  as?: keyof HTMLElementTagNameMap;
};

export type StaticFlowColumnsRenderContext = {
  /** Stable identity only: column geometry callbacks must return the same layout on every page. */
  flowId: string;
};

export type StaticFlowColumnsContainerProps = {
  className?: string;
  style?: React.CSSProperties;
};

type FlowColumnsProps<TItem, TType extends string = DefaultFlowItemType<TItem>> =
  FlowProps<TItem, TType> & {
    /** One-level story layout. Recursive columns are intentionally unsupported. */
    layout: StaticFlowLayoutNode[];
    getColumnGroupProps?: (
      node: Extract<StaticFlowLayoutNode, { kind: 'columns' }>,
      context: StaticFlowColumnsRenderContext
    ) => StaticFlowColumnsContainerProps | undefined;
    getColumnProps?: (
      node: Extract<StaticFlowLayoutNode, { kind: 'columns' }>,
      column: StaticFlowColumn,
      context: StaticFlowColumnsRenderContext
    ) => StaticFlowColumnsContainerProps | undefined;
    getColumnItemProps?: (
      node: Extract<StaticFlowLayoutNode, { kind: 'columns' }>,
      column: StaticFlowColumn,
      itemIndex: number,
      context: StaticFlowColumnsRenderContext
    ) => StaticFlowColumnsContainerProps | undefined;
  };

export function Flow<TItem, TType extends string = DefaultFlowItemType<TItem>>({
  id,
  items,
  getKey,
  renderItem,
  getItemMeta,
  metaDefaults,
  getItemType: resolveItemType,
  getItemGroup,
  renderGroupHeader,
  className = '',
  itemClassName,
  groupHeaderClassName,
  renderUnplaceableItem,
  asChild = false,
  as = 'div',
}: FlowProps<TItem, TType>) {
  const context = React.useContext(StaticFlowContext);
  // The piece of an outer Flow's item this Flow renders in: its group headers are not that piece.
  const outerSplit = React.useContext(FlowTextSplitContext);
  const Root = as as React.ElementType;
  const chunks = context?.chunksByFlowId?.[id];
  const activeChunk = context?.mode === 'visible' && chunks
    ? chunks[context.pageIndex]
    : undefined;
  const pageIndex = context?.mode === 'visible' ? context.pageIndex : 0;
  const pageCount = context?.mode === 'visible' && chunks ? chunks.length : 1;
  const unplaceable = activeChunk?.unplaceable;
  // A custom renderer that returns nothing falls back to the default, as before.
  const customUnplaceable = unplaceable
    ? renderUnplaceableItem?.(unplaceable, { flowId: id, pageIndex, pageCount })
    : undefined;
  const renderOriginalUnplaceable = Boolean(unplaceable && customUnplaceable == null);
  // A continuation measurement copy only lays the region out: its height is all that is read.
  const plannedIndexes = context?.copy === 'continuation'
    ? []
    : context?.mode === 'visible' && chunks
      ? (activeChunk?.indexes ?? [])
      : context?.mode === 'visible' && context.pageIndex > 0
        ? []
        : items.map((_, index) => index);
  // Preview and export render the same document content. Diagnostics are separate.
  const rawVisibleIndexes = renderOriginalUnplaceable
    ? [...new Set([...plannedIndexes, unplaceable!.index])].sort((a, b) => a - b)
    : plannedIndexes;

  // Guard against stale chunk indexes when items shrink (e.g. rowCount decreased before remeasure)
  const visibleIndexes = rawVisibleIndexes.filter((idx) => (
    Number.isInteger(idx) && idx >= 0 && idx < items.length
  ));
  const itemGroups = items.map((item, index) => normalizeItemGroup(getItemGroup?.(item, index)));
  const groupKeys = itemGroups.map((group) => group?.key);
  const fragmentPositions = getFirstFragmentPositions(visibleIndexes);
  const plannedGroupHeaders = renderGroupHeader
    ? getPlannedGroupHeadersByItemIndex(activeChunk?.groupHeaders)
    : undefined;

  React.useEffect(() => {
    if (!isDev() || !metaDefaults || !Object.keys(metaDefaults).length || !items.length) {
      return;
    }

    const warningKey = `${id}:${Object.keys(metaDefaults).join('|')}`;
    if (warnedMetaDefaultsWithoutType.has(warningKey)) return;

    const hasResolvableType = items.some((item, index) => (
      Boolean(resolveItemType?.(item, index) ?? getItemType(item))
    ));
    if (hasResolvableType) return;

    warnedMetaDefaultsWithoutType.add(warningKey);
    console.warn(
      `[uhuu-components] Static.Flow "${id}" received metaDefaults, but no item type could be resolved. ` +
      'Add a type field to each item or pass getItemType so defaults can be applied.'
    );
  }, [id, items, metaDefaults, resolveItemType]);

  return (
    <Root
      className={className}
      data-uhuu-flow="true"
      data-uhuu-flow-id={id}
      data-uhuu-flow-as-child={asChild ? 'true' : undefined}
      data-uhuu-flow-item-count={asChild && context?.mode !== 'visible' ? visibleIndexes.length : undefined}
    >
      {unplaceable && customUnplaceable != null && ((asChild && cloneAsChild(customUnplaceable, {
        'data-uhuu-flow-unplaceable': 'true',
        'data-uhuu-flow-unplaceable-key': unplaceable.key,
      }, { flowId: id, source: 'renderUnplaceableItem' })) || (
        <div
          // No box of its own: a template's fallback lays out exactly as when it was returned bare.
          style={{ display: 'contents' }}
          data-uhuu-flow-unplaceable="true"
          data-uhuu-flow-unplaceable-key={unplaceable.key}
        >
          {customUnplaceable}
        </div>
      ))}
      {visibleIndexes.map((itemIndex) => {
        const item = items[itemIndex];
        if (item === undefined) return null;

        const key = getKey(item, itemIndex);
        const group = itemGroups[itemIndex];
        const coreFragment = getFlowFragmentState({
          itemIndex,
          fragmentIndexes: visibleIndexes,
          fragmentIndex: fragmentPositions.get(itemIndex) ?? -1,
          groupKeys,
          pageIndex,
          pageCount,
          itemCount: items.length,
        });
        const split = activeChunk?.splits?.[itemIndex];
        const fragment: StaticFlowFragmentContext<TItem> = {
          ...coreFragment,
          flowId: id,
          itemKey: key,
          item,
          ...(split ? splitFragment(split, coreFragment) : {}),
        };
        const type = resolveItemType?.(item, itemIndex) ?? (getItemType(item) as TType | undefined);
        const meta = mergeItemMeta(
          type ? metaDefaults?.[type] : undefined,
          getItemMeta?.(item, itemIndex)
        );
        const resolvedItemClassName =
          typeof itemClassName === 'function'
            ? itemClassName(item, itemIndex)
            : itemClassName;
        const hasPlannedGroupHeader = Boolean(
          group && plannedGroupHeaders?.get(itemIndex)?.has(group.key)
        );
        const shouldRenderGroupHeader = Boolean(
          group &&
          renderGroupHeader &&
          (
            hasPlannedGroupHeader || (
              !plannedGroupHeaders &&
              fragment.isFirstInGroupOnPage &&
              (fragment.isFirstInGroup || group.repeatHeader !== false)
            )
          )
        );
        const resolvedGroupHeaderClassName: string | undefined =
          typeof groupHeaderClassName === 'function'
            ? (group ? groupHeaderClassName(group, fragment) : undefined)
            : groupHeaderClassName;
        const isOriginalUnplaceable = renderOriginalUnplaceable && itemIndex === unplaceable?.index;
        const fitStyle = isOriginalUnplaceable ? unplaceableFitStyle(unplaceable!) : undefined;
        const headerContent = shouldRenderGroupHeader && group ? renderGroupHeader?.(group, fragment) : undefined;
        const headerAttributes: FlowElementProps = {
          'data-uhuu-flow-group-header': 'true',
          'data-uhuu-flow-header-group-key': group?.key,
        };
        const content = renderItem(item, itemIndex, fragment);
        const itemAttributes: FlowElementProps = {
          'data-uhuu-flow-item': 'true',
          'data-uhuu-flow-key': String(key),
          'data-uhuu-flow-index': itemIndex,
          'data-uhuu-flow-break-before': meta.breakBefore ? 'true' : undefined,
          'data-uhuu-flow-break-after': meta.breakAfter ? 'true' : undefined,
          'data-uhuu-flow-keep-with-next': serializeKeepWithNext(meta.keepWithNext),
          'data-uhuu-flow-avoid-break-inside': meta.avoidBreakInside ? 'true' : undefined,
          'data-uhuu-flow-group-key': meta.groupKey,
          'data-uhuu-flow-header-group-key': group?.key,
          'data-uhuu-flow-header-repeat': group ? (group.repeatHeader === false ? 'false' : 'true') : undefined,
          'data-uhuu-flow-unplaceable': isOriginalUnplaceable ? 'true' : undefined,
          'data-uhuu-flow-unplaceable-key': isOriginalUnplaceable ? unplaceable!.key : undefined,
          'data-uhuu-flow-orphans': serializeLineCount(meta.orphans),
          'data-uhuu-flow-widows': serializeLineCount(meta.widows),
          'data-uhuu-flow-split': split ? splitPosition(split) : undefined,
        };

        const header = shouldRenderGroupHeader && group
          ? (asChild && cloneAsChild(headerContent, {
            className: resolvedGroupHeaderClassName,
            ...headerAttributes,
          }, { flowId: id, source: 'renderGroupHeader' })) || (
            <div
              className={resolvedGroupHeaderClassName}
              style={{ display: 'flow-root' }}
              {...headerAttributes}
            >
              {headerContent}
            </div>
          )
          : null;
        const element = (asChild && cloneAsChild(content, {
          className: resolvedItemClassName,
          ...itemAttributes,
        }, { flowId: id, source: 'renderItem', forcedStyle: fitStyle })) || (
          <div
            className={resolvedItemClassName}
            style={{
              display: 'flow-root',
              ...fitStyle,
            }}
            {...itemAttributes}
          >
            {content}
          </div>
        );

        // The piece this item renders, for its Static.FlowText (none: the whole item). Always
        // provided, so a re-plan that splits an item does not remount it, and a Flow nested in a
        // split piece does not hand that piece to its own items.
        return (
          <React.Fragment key={key}>
            {outerSplit ? shadowSplit(header) : header}
            <FlowTextSplitContext.Provider value={split ?? null}>{element}</FlowTextSplitContext.Provider>
          </React.Fragment>
        );
      })}
    </Root>
  );
}

export function FlowColumns<TItem, TType extends string = DefaultFlowItemType<TItem>>({
  id,
  items,
  layout,
  getKey,
  renderItem,
  getItemMeta,
  metaDefaults,
  getItemType: resolveItemType,
  getItemGroup,
  renderGroupHeader,
  className = '',
  itemClassName,
  groupHeaderClassName,
  renderUnplaceableItem,
  getColumnGroupProps,
  getColumnProps,
  getColumnItemProps,
  asChild = false,
  as = 'div',
}: FlowColumnsProps<TItem, TType>) {
  validateFlowColumnLayout({ nodes: layout, itemCount: items.length });
  const context = React.useContext(StaticFlowContext);
  const outerSplit = React.useContext(FlowTextSplitContext);
  const Root = as as React.ElementType;
  const continuationCopy = context?.copy === 'continuation';
  const chunks = context?.chunksByFlowId?.[id];
  const activeChunk = context?.mode === 'visible' && chunks
    ? chunks[context.pageIndex]
    : undefined;
  const isMeasurement = context?.mode !== 'visible';
  const pageIndex = context?.mode === 'visible' ? context.pageIndex : 0;
  const pageCount = context?.mode === 'visible' && chunks ? chunks.length : 1;
  const itemGroups = items.map((item, index) => normalizeItemGroup(getItemGroup?.(item, index)));
  const groupKeys = itemGroups.map((entry) => entry?.key);
  const columnsContext: StaticFlowColumnsRenderContext = {
    flowId: id,
  };

  React.useEffect(() => {
    if (!isDev() || !metaDefaults || !Object.keys(metaDefaults).length || !items.length) {
      return;
    }

    const warningKey = `${id}:columns:${Object.keys(metaDefaults).join('|')}`;
    if (warnedMetaDefaultsWithoutType.has(warningKey)) return;
    const hasResolvableType = items.some((item, index) => (
      Boolean(resolveItemType?.(item, index) ?? getItemType(item))
    ));
    if (hasResolvableType) return;

    warnedMetaDefaultsWithoutType.add(warningKey);
    console.warn(
      `[uhuu-components] Static.FlowColumns "${id}" received metaDefaults, but no item type could be resolved. ` +
      'Add a type field to each item or pass getItemType so defaults can be applied.'
    );
  }, [id, items, metaDefaults, resolveItemType]);

  const renderUnplaceable = (
    unplaceable: StaticFlowUnplaceableItem | undefined,
    printItem: () => React.ReactNode
  ): React.ReactNode => {
    if (!unplaceable) return null;
    // A custom renderer that returns nothing falls back to the default, as before.
    const custom = renderUnplaceableItem?.(unplaceable, { flowId: id, pageIndex, pageCount });
    if (custom == null) return printItem();
    const cloned = asChild && cloneAsChild(custom, {
      'data-uhuu-flow-unplaceable': 'true',
      'data-uhuu-flow-unplaceable-key': unplaceable.key,
      'data-uhuu-flow-column-id': unplaceable.columnId,
    }, { flowId: id, source: 'renderUnplaceableItem' });
    if (cloned) return cloned;
    return (
      <div
        style={{ display: 'contents' }}
        data-uhuu-flow-unplaceable="true"
        data-uhuu-flow-unplaceable-key={unplaceable.key}
        data-uhuu-flow-column-id={unplaceable.columnId}
      >
        {custom}
      </div>
    );
  };

  const renderIndexes = (
    rawIndexes: number[],
    plannedChunk?: StaticFlowChunk,
    resolveContainerProps?: (itemIndex: number) => StaticFlowColumnsContainerProps | undefined,
    markAsLayoutNode = false,
    sourceTrackIndexes?: number[]
  ): React.ReactNode[] => {
    const visibleIndexes = rawIndexes.filter((itemIndex) => (
      Number.isInteger(itemIndex) && itemIndex >= 0 && itemIndex < items.length
    ));
    const fragmentPositions = getFirstFragmentPositions(visibleIndexes);
    const sourceTrackPositions = sourceTrackIndexes
      ? getFirstFragmentPositions(sourceTrackIndexes)
      : undefined;
    const plannedGroupHeaders = renderGroupHeader
      ? getPlannedGroupHeadersByItemIndex(plannedChunk?.groupHeaders)
      : undefined;

    return visibleIndexes.map((itemIndex) => {
      const item = items[itemIndex];
      if (item === undefined) return null;
      const key = getKey(item, itemIndex);
      const group = itemGroups[itemIndex];
      const fragmentIndex = fragmentPositions.get(itemIndex) ?? -1;
      const sourceTrackPosition = sourceTrackPositions?.get(itemIndex) ?? -1;
      const coreFragment = getFlowFragmentState({
        itemIndex,
        fragmentIndexes: visibleIndexes,
        fragmentIndex,
        groupKeys,
        pageIndex,
        pageCount,
        itemCount: items.length,
        previousSourceIndex: plannedChunk?.previousSourceIndex ?? (
          sourceTrackPosition > 0 ? sourceTrackIndexes?.[sourceTrackPosition - 1] : undefined
        ),
      });
      const fragment: StaticFlowFragmentContext<TItem> = {
        ...coreFragment,
        flowId: id,
        itemKey: key,
        item,
      };
      const type = resolveItemType?.(item, itemIndex) ?? (getItemType(item) as TType | undefined);
      const meta = mergeItemMeta(
        type ? metaDefaults?.[type] : undefined,
        getItemMeta?.(item, itemIndex)
      );
      const resolvedItemClassName =
        typeof itemClassName === 'function'
          ? itemClassName(item, itemIndex)
          : itemClassName;
      const containerProps = resolveContainerProps?.(itemIndex);
      const hasPlannedGroupHeader = Boolean(
        group && plannedGroupHeaders?.get(itemIndex)?.has(group.key)
      );
      const shouldRenderGroupHeader = Boolean(
        group &&
        renderGroupHeader &&
        (
          hasPlannedGroupHeader || (
            !plannedGroupHeaders &&
            fragment.isFirstInGroupOnPage &&
            (fragment.isFirstInGroup || group.repeatHeader !== false)
          )
        )
      );
      const resolvedGroupHeaderClassName: string | undefined =
        typeof groupHeaderClassName === 'function'
          ? (group ? groupHeaderClassName(group, fragment) : undefined)
          : groupHeaderClassName;
      const plannedUnplaceable = plannedChunk?.unplaceable?.index === itemIndex ? plannedChunk.unplaceable : undefined;
      const fitStyle = plannedUnplaceable ? unplaceableFitStyle(plannedUnplaceable) : undefined;
      const itemClass = [resolvedItemClassName, containerProps?.className].filter(Boolean).join(' ');
      const headerContent = shouldRenderGroupHeader && group ? renderGroupHeader?.(group, fragment) : undefined;
      const headerAttributes: FlowElementProps = {
        'data-uhuu-flow-group-header': 'true',
        'data-uhuu-flow-header-group-key': group?.key,
      };
      const content = renderItem(item, itemIndex, fragment);
      const itemAttributes: FlowElementProps = {
        'data-uhuu-flow-item': 'true',
        'data-uhuu-flow-layout-node': markAsLayoutNode ? 'item' : undefined,
        'data-uhuu-flow-key': String(key),
        'data-uhuu-flow-index': itemIndex,
        'data-uhuu-flow-unplaceable': plannedUnplaceable ? 'true' : undefined,
        'data-uhuu-flow-unplaceable-key': plannedUnplaceable?.key,
        'data-uhuu-flow-column-id': plannedUnplaceable?.columnId,
        'data-uhuu-flow-break-before': meta.breakBefore ? 'true' : undefined,
        'data-uhuu-flow-break-after': meta.breakAfter ? 'true' : undefined,
        'data-uhuu-flow-keep-with-next': serializeKeepWithNext(meta.keepWithNext),
        'data-uhuu-flow-avoid-break-inside': meta.avoidBreakInside ? 'true' : undefined,
        'data-uhuu-flow-group-key': meta.groupKey,
        'data-uhuu-flow-header-group-key': group?.key,
        'data-uhuu-flow-header-repeat': group ? (group.repeatHeader === false ? 'false' : 'true') : undefined,
      };

      const header = shouldRenderGroupHeader && group
        ? (asChild && cloneAsChild(headerContent, {
          className: resolvedGroupHeaderClassName,
          ...headerAttributes,
        }, { flowId: id, source: 'renderGroupHeader' })) || (
          <div
            className={resolvedGroupHeaderClassName}
            style={{ display: 'flow-root' }}
            {...headerAttributes}
          >
            {headerContent}
          </div>
        )
        : null;
      const element = (asChild && cloneAsChild(content, {
        className: itemClass || undefined,
        ...itemAttributes,
      }, {
        flowId: id,
        source: 'renderItem',
        baseStyle: containerProps?.style,
        forcedStyle: fitStyle,
      })) || (
        <div
          className={itemClass}
          style={{
            display: 'flow-root',
            ...containerProps?.style,
            ...fitStyle,
          }}
          {...itemAttributes}
        >
          {content}
        </div>
      );

      return (
        <React.Fragment key={key}>
          {outerSplit ? shadowSplit(header) : header}
          {outerSplit ? shadowSplit(element) : element}
        </React.Fragment>
      );
    });
  };

  const sourceColumnNodes = new Map(
    layout
      .filter((node): node is Extract<StaticFlowLayoutNode, { kind: 'columns' }> => (
        node.kind === 'columns'
      ))
      .map((node) => [node.id, node])
  );
  // A continuation measurement copy only lays the region out: its height is all that is read.
  const renderedLayout = continuationCopy
    ? []
    : isMeasurement
      ? layout
      : (activeChunk?.layout ?? []);

  return (
    <Root
      className={className}
      data-uhuu-flow="true"
      data-uhuu-flow-id={id}
      data-uhuu-flow-layout="columns"
      data-uhuu-flow-as-child={asChild ? 'true' : undefined}
      data-uhuu-flow-item-count={asChild && isMeasurement ? (continuationCopy ? 0 : items.length) : undefined}
    >
      {renderedLayout.map((entry, layoutIndex) => {
        if (entry.kind === 'item') {
          return (
            <React.Fragment key={`item:${entry.index}:${layoutIndex}`}>
              {renderIndexes([entry.index], undefined, undefined, true)}
            </React.Fragment>
          );
        }
        if (entry.kind === 'items') {
          return (
            <React.Fragment key={`items:${layoutIndex}`}>
              {renderUnplaceable(
                entry.chunk.unplaceable,
                () => renderIndexes([entry.chunk.unplaceable!.index], entry.chunk, undefined, true)
              )}
              {renderIndexes(entry.chunk.indexes, entry.chunk, undefined, true)}
            </React.Fragment>
          );
        }

        const sourceNode = isMeasurement
          ? (entry as Extract<StaticFlowLayoutNode, { kind: 'columns' }>)
          : sourceColumnNodes.get(entry.id);
        if (!sourceNode) return null;
        const sourceColumnsById = new Map(sourceNode.columns.map((column) => [column.id, column]));
        const renderedColumns: Array<{ id: string; chunk?: StaticFlowChunk }> = isMeasurement
          ? sourceNode.columns.map((column) => ({ id: column.id }))
          : (entry as Extract<StaticFlowLayoutFragment, { kind: 'columns' }>).columns;
        const groupProps = getColumnGroupProps?.(sourceNode, columnsContext);

        return (
          <div
            key={`columns:${sourceNode.id}:${layoutIndex}`}
            className={groupProps?.className}
            style={{
              display: 'flex',
              width: '100%',
              alignItems: 'flex-start',
              ...groupProps?.style,
            }}
            data-uhuu-flow-layout-node="columns"
            data-uhuu-flow-layout-id={sourceNode.id}
          >
            {renderedColumns.map((renderedColumn) => {
              const sourceColumn = sourceColumnsById.get(renderedColumn.id);
              if (!sourceColumn) return null;
              const columnProps = getColumnProps?.(sourceNode, sourceColumn, columnsContext);
              const columnIndexes = renderedColumn.chunk?.indexes ?? sourceColumn.indexes;

              return (
                <div
                  key={sourceColumn.id}
                  className={columnProps?.className}
                  style={{
                    minWidth: 0,
                    flex: '1 1 0%',
                    display: 'flex',
                    flexDirection: 'column',
                    ...columnProps?.style,
                  }}
                  data-uhuu-flow-column={sourceColumn.id}
                >
                  {renderUnplaceable(
                    renderedColumn.chunk?.unplaceable,
                    () => renderIndexes(
                      [renderedColumn.chunk!.unplaceable!.index],
                      renderedColumn.chunk,
                      (itemIndex) => getColumnItemProps?.(sourceNode, sourceColumn, itemIndex, columnsContext),
                      false,
                      sourceColumn.indexes
                    )
                  )}
                  {renderIndexes(
                    columnIndexes,
                    renderedColumn.chunk,
                    (itemIndex) => getColumnItemProps?.(
                      sourceNode,
                      sourceColumn,
                      itemIndex,
                      columnsContext
                    ),
                    false,
                    sourceColumn.indexes
                  )}
                </div>
              );
            })}
          </div>
        );
      })}
    </Root>
  );
}
